          default_tenant_mode: 'Provisionnement de l\'espace de travail après une inscription publique. create_personal crée un espace de travail dont l\'utilisateur est propriétaire ; tenantless crée uniquement le compte jusqu\'à ce que l\'utilisateur accepte une invitation ou crée un espace de travail. S\'applique uniquement aux nouveaux utilisateurs.',
          complex_password_enabled: 'Exiger ou non des mots de passe complexes. Lorsque cette option est activée, les mots de passe doivent contenir des majuscules, des minuscules, des chiffres et des caractères spéciaux. Les modifications prennent effet immédiatement et ne s\'appliquent qu\'aux utilisateurs nouvellement inscrits ou aux nouveaux changements/réinitialisations de mot de passe. Les caractères spéciaux incluent {specialChars}'
