          enrichment_concurrency: 'Concurrence garantie par processus pour les résumés, images, graphe et génération de questions. Enrichment peut aussi emprunter le pool élastique partagé. Minimum 1 ; nécessite un redémarrage du service.',
          maintenance_concurrency: 'Concurrence par processus pour la synchronisation des sources, les traitements par lot et le nettoyage, strictement isolée du pipeline exposé aux utilisateurs. Minimum 1 ; nécessite un redémarrage du service.',
          shared_concurrency: 'Concurrence élastique par processus partagée entre l\'analyse core et l\'enrichissement ; le côté qui a un arriéré l\'emprunte automatiquement. Minimum 1 ; nécessite un redémarrage du service.',
          wiki_concurrency: 'Concurrence par processus pour le pool de workers wiki dédié, isolé des tâches en amont. Minimum 1 ; nécessite un redémarrage du service.'
