  // Display text for the observed image attributes, keyed by attribute name.
  // Attribute names escape their dots (contain.text → contain_text) because
  // vue-i18n walks a key segment by segment on the dots, so a literal
  // 'contain.text' key would never resolve. An attribute without a translation
  // falls back to the registry's own wording.
  //
  // Every value carries a short label for compact controls (a filter
  // checkbox) and a description for wherever there is room (a tooltip). One
  // bundle therefore serves both the settings panel and the image gallery,
  // including the gallery's fallback for attributes it does not declare.
  imageAttr: {
    contain_text: {
      label: 'Texte dans l\'image',
      description: 'Quantité de texte courant portée par l\'image elle-même. Détermine si la lecture de ce texte justifie un passage OCR distinct.',
      values: {
        none: { label: 'Aucun', description: 'aucun texte' },
        sparse: { label: 'Épars', description: 'quelques mots — un logo, un panneau routier, une seule étiquette' },
        block: { label: 'Bloc', description: 'un bloc de texte courant — une capture d\'écran, un tableau, une page de document' }
      }
    },
    contain_data_visual: {
      label: 'Visualisation de données',
      description: 'Indique si l\'image transmet des données sous forme de graphique, de diagramme ou d\'infographie. Ces images conservent leurs libellés dans le circuit OCR même lorsque le texte semble épars.',
      values: {
        'true': { label: 'Oui', description: 'un graphique ou un diagramme avec des valeurs tracées' },
        'false': { label: 'Non', description: 'une photo, un dessin, une icône ou une décoration' }
      }
    },
    layout_margin: {
      label: 'Zone sans texte',
      description:
        'Quantité de fond qui entoure le contenu. De grandes marges signifient que la page peut être recadrée plus serré avant la lecture par l\'OCR.',
      values: {
        'none': { label: 'Aucune', description: 'le texte atteint les bords' },
        'small': { label: 'Petite', description: 'une fine bande de fond' },
        'large': { label: 'Grande', description: 'beaucoup de zone sans texte : un bureau, une pièce, une page presque vide' }
      }
    },
    layout_upright: {
      label: 'Orientation du texte',
      description:
        'Indique si le texte se lit dans le bon sens. Une page pivotée ou à l\'envers mérite d\'être redressée avant la lecture par l\'OCR.',
      values: {
        'true': { label: 'Droit', description: 'le texte se lit dans son orientation normale' },
        'false': { label: 'Pivoté', description: 'le texte est tourné, incliné ou à l\'envers' }
      }
    }
  },
  // Overlay wording for the pipeline panel, indexed by pipeline id and field
  // key (the backend registry supplies both; this only translates). Anything
  // not covered here falls back to the backend's own wording, so a new
  // pipeline never shows up as a bare key.
