          description: 'Laisse le modèle réfléchir avant de transcrire le texte. En général, la réflexion n\'est pas nécessaire ; l\'activer ralentit l\'analyse et peut pousser le modèle à trop réfléchir, un raisonnement trop long pouvant dépasser la limite et tronquer le texte transcrit, ce qui fait échouer la tâche. Ne l\'activez que si vous avez confirmé que c\'est nécessaire.',
